import io
from datetime import datetime


def generate_markdown_report(result: dict) -> str:
    """Generate a clean, structured Markdown report from meeting analysis results."""
    date_str = datetime.now().strftime("%Y-%m-%d %H:%M")
    md = f"""# {result.get('title', 'Meeting Notes')}
*Generated by AI Video Assistant on {date_str}*

---

## 📋 Executive Summary
{result.get('summary', 'N/A')}

---

## ✅ Action Items
{result.get('action_items', 'N/A')}

---

## 🔑 Key Decisions
{result.get('key_decisions', 'N/A')}

---

## ❓ Open Questions & Follow-ups
{result.get('open_questions', 'N/A')}

---

## 📝 Full Transcript
{result.get('transcript', 'N/A')}
"""
    return md


def generate_pdf_report(result: dict) -> bytes:
    """
    Generate a formatted PDF report using reportlab or fpdf2.
    Returns bytes suitable for Streamlit download_button.
    """
    try:
        from reportlab.lib.pagesizes import letter
        from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
        from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, HRFlowable
        from reportlab.lib import colors

        buffer = io.BytesIO()
        doc = SimpleDocTemplate(
            buffer,
            pagesize=letter,
            rightMargin=54,
            leftMargin=54,
            topMargin=54,
            bottomMargin=54,
        )
        styles = getSampleStyleSheet()

        # Custom styles
        title_style = ParagraphStyle(
            "DocTitle",
            parent=styles["Heading1"],
            fontSize=20,
            leading=24,
            textColor=colors.HexColor("#1e1e2f"),
            spaceAfter=6,
        )
        sub_style = ParagraphStyle(
            "DocSub",
            parent=styles["Normal"],
            fontSize=9,
            leading=12,
            textColor=colors.HexColor("#6b7280"),
            spaceAfter=15,
        )
        h2_style = ParagraphStyle(
            "DocH2",
            parent=styles["Heading2"],
            fontSize=13,
            leading=16,
            textColor=colors.HexColor("#4f46e5"),
            spaceBefore=12,
            spaceAfter=6,
        )
        body_style = ParagraphStyle(
            "DocBody",
            parent=styles["BodyText"],
            fontSize=9,
            leading=14,
            textColor=colors.HexColor("#1f2937"),
            spaceAfter=10,
        )

        elements = []
        date_str = datetime.now().strftime("%Y-%m-%d %H:%M")
        title = result.get("title", "Meeting Notes").replace("\n", " ")

        elements.append(Paragraph(title, title_style))
        elements.append(Paragraph(f"Generated by AI Video Assistant | {date_str}", sub_style))
        elements.append(HRFlowable(width="100%", thickness=1, color=colors.HexColor("#e5e7eb"), spaceAfter=12))

        sections = [
            ("Executive Summary", result.get("summary", "")),
            ("Action Items", result.get("action_items", "")),
            ("Key Decisions", result.get("key_decisions", "")),
            ("Open Questions & Follow-ups", result.get("open_questions", "")),
        ]

        for heading, content in sections:
            elements.append(Paragraph(heading, h2_style))
            # Format newlines into paragraphs
            for para in content.split("\n"):
                clean_p = para.strip()
                if clean_p:
                    elements.append(Paragraph(clean_p, body_style))
            elements.append(Spacer(1, 8))

        doc.build(elements)
        buffer.seek(0)
        return buffer.getvalue()

    except Exception:
        # Fallback to plain text bytes if reportlab has rendering errors
        md_text = generate_markdown_report(result)
        return md_text.encode("utf-8")
